"""HubGPT Voice - your own voice for Sukoon, generated by a voice model trained on your recordings.
HubGPT voice engine: paths come from the HubGPT root config.json. Shared resources only:
the Python with PyTorch (config python / shared_pythons), models in hf_models, ffmpeg.

    run.py              menu
    run.py setup | dataset [--rebuild] | train [--new] [--epochs N] | test [--model X] | speak <script> [...]
"""
import json, os, sys, time

ROOT = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, ROOT)
from voice import cfg  # noqa: E402

sys.path.insert(0, cfg.LIBS)                              # ComfyUI's Python ignores PYTHONPATH (._pth file)
for k, v in {"HF_HOME": cfg.C["hf_models"], "HF_HUB_DISABLE_XET": "1", "HF_HUB_DISABLE_PROGRESS_BARS": "1", "TQDM_DISABLE": "1", "TRANSFORMERS_VERBOSITY": "error",
             "TORCH_HOME": os.path.join(cfg.CACHE, "torch"), "PIP_CACHE_DIR": os.path.join(cfg.CACHE, "pip"),
             "NUMBA_CACHE_DIR": os.path.join(cfg.CACHE, "numba"), "PYTHONWARNINGS": "ignore"}.items():
    os.environ[k] = v
try:
    os.makedirs(cfg.TMP, exist_ok=True)
    os.environ["TEMP"] = os.environ["TMP"] = cfg.TMP          # temp files on D:, never C:
except OSError:
    pass


class Tee:
    def __init__(self, *s):
        self.s = s

    def write(self, x):
        for s in self.s:
            try:
                s.write(x); s.flush()
            except Exception:
                pass

    def flush(self):
        for s in self.s:
            try:
                s.flush()
            except Exception:
                pass

    def isatty(self):
        return False                                    # no colour codes / progress-bar tricks in the log

    def __getattr__(self, name):                        # anything else (encoding, fileno, ...) = the real window
        return getattr(self.s[0], name)


def status():
    meta = cfg.read_meta()
    if meta:
        mins = sum(m["dur"] for m in meta) / 60
        print(f"  dataset : {len(meta)} lines = {mins:.1f} min of your voice   ({cfg.DATASET})")
    else:
        print("  dataset : not built yet")
    rs = cfg.runs()
    if rs:
        n, d = rs[0]
        done = os.path.join(d, "done.txt")
        print(f"  training: {n}  -  " + (open(done, encoding="utf-8").read().strip() if os.path.exists(done) else
                                         "unfinished (2 continues it)" if os.path.exists(os.path.join(d, "last.pt"))
                                         else "started"))
    else:
        print("  training: not yet")
    print(f"  speaking with: {cfg.best_checkpoint() or 'plain clone (no training yet)'}")


def menu():
    while True:
        print("\n" + "=" * 70 + "\n  SUKOON VOICE  -  your voice, generated\n" + "=" * 70)
        status()
        print("""
  1  build / update the dataset from your episodes + Audacity recordings  (GPU; first time ~30 min)
  2  train your voice  (asks which style; GPU must be free - close ComfyUI; ~30-45 min)
  3  A/B test: YOUR real lines vs plain clone vs trained voice
  4  speak a script  (path of a script.txt or an episode folder)
  5  open the output folder
  6  build your breath library (from your Sukoon recordings, ~2 min; then delete the bad ones)
  7  voice prompt test: which sample of you gives the best tone (smile / warmth)?
  8  smile finder: pick your faintly smiling Sukoon clips by sound (formants), ~2 min
  Q  quit""")
        c = input("  choose: ").strip().lower()
        try:
            if c == "1":
                from voice import dataset; dataset.main()
            elif c == "2":
                from voice import train
                print("\n  which voice to train?")
                keys = list(train.PROFILES)
                for i, k in enumerate(keys, 1):
                    print(f"    {i}  {train.PROFILES[k]}" + ("   (recommended)" if i == 1 else ""))
                ch = input("  choose [1]: ").strip() or "1"
                prof = keys[int(ch) - 1] if ch.isdigit() and 0 < int(ch) <= len(keys) else keys[0]
                train.main(profile=prof)
            elif c == "3":
                from voice import abtest; abtest.main()
            elif c == "4":
                p = input("  script .txt or episode folder (drag it here): ").strip().strip('"')
                if p:
                    st = input("  style = which recording's tone (Enter = Sukoon; or e.g. Burari Kand): ").strip()
                    pc = input("  pace (Enter = your own; or: slower / faster / more pauses / fewer pauses, "
                               "can combine e.g. 'slower more pauses'): ").strip()
                    from voice import speak; speak.main(p, style=st or None, pace=pc or None)
            elif c == "8":
                from voice import smile; smile.main()
            elif c == "7":
                from voice import prompts; prompts.main()
            elif c == "6":
                from voice import breaths; breaths.build()
            elif c == "5":
                os.makedirs(cfg.MEDIA, exist_ok=True); os.startfile(cfg.MEDIA)
            elif c in ("q", ""):
                return
        except SystemExit as e:
            print(f"\n  !! {e}")
        except Exception:
            import traceback; traceback.print_exc()
            print("\n  !! something failed - the whole window text is in logs\\last_run.txt")


def opt(args, name, default=None):
    if name in args:
        i = args.index(name)
        v = args[i + 1] if i + 1 < len(args) and not args[i + 1].startswith("--") else True
        del args[i:i + (2 if v is not True else 1)]
        return v
    return default


def main():
    os.makedirs(os.path.join(ROOT, "logs"), exist_ok=True)
    log = open(os.path.join(ROOT, "logs", os.environ.get("SV_LOGNAME") or "last_run.txt"), "w", encoding="utf-8")
    log.write(f"{time.strftime('%Y-%m-%d %H:%M')}  {' '.join(sys.argv)}\n")
    for s in (sys.stdout, sys.stderr):
        try:
            s.reconfigure(encoding="utf-8", errors="replace")
        except Exception:
            pass
    sys.stdout = Tee(sys.__stdout__, log); sys.stderr = Tee(sys.__stderr__, log)
    a = sys.argv[1:]
    cmd = a.pop(0).lower() if a else "menu"
    try:
        if cmd == "menu":
            menu()
        elif cmd == "setup":
            from voice import install; install.main()
        elif cmd == "dataset":
            from voice import dataset
            dataset.main(rebuild=bool(opt(a, "--rebuild", False)), skip_recordings=bool(opt(a, "--no-recordings", False)))
        elif cmd == "train":
            from voice import train
            train.main(new=bool(opt(a, "--new", False)), epochs=opt(a, "--epochs"), profile=opt(a, "--profile"),
                       lr=opt(a, "--lr"), limit=opt(a, "--limit"),
                       name=(a[0] if a else None))
        elif cmd == "auto":                      # unattended: train Sukoon calm -> prompt test (+ smile ranking)
            from voice import train, prompts
            print("\n=== AUTO 1/2: training Sukoon calm (stops by itself) ===")
            train.main(new=True, profile="sukoon_calm")
            print("\n=== AUTO 2/2: voice prompt test with every sample ===")
            prompts.main()
            print("\n=== AUTO DONE - Claude can read the results ===")
        elif cmd == "flowdata":                  # several lines in a row with your real pauses (for profile sukoon_flow)
            from voice import flowdata; flowdata.main()
        elif cmd == "s3train":
            from voice import s3train
            s3train.main(epochs=int(opt(a, "--epochs", 8)), lr=float(opt(a, "--lr", 1e-5)), limit=opt(a, "--limit"),
                         profile=opt(a, "--profile", "sukoon_calm"))
        elif cmd == "grid":
            from voice import grid; grid.main(opt(a, "--script"), smoke=bool(opt(a, "--smoke", False)))
        elif cmd == "score":
            from voice import grid; grid.score(opt(a, "--dir"))
        elif cmd == "final":
            from voice import grid; grid.final(" ".join(a).strip('"'))
        elif cmd == "test":
            from voice import abtest; abtest.main(model=opt(a, "--model"), n=opt(a, "--n"))
        elif cmd == "speak":
            from voice import speak
            name, model, redo, style = opt(a, "--name"), opt(a, "--model"), opt(a, "--redo", ""), opt(a, "--style")
            pace = opt(a, "--pace")
            s3g = opt(a, "--s3gen")
            flow = opt(a, "--flow")
            ov = {}
            while "--set" in a:                          # --set exaggeration=0.35  (this run only)
                kv = str(opt(a, "--set"))
                k, _, v = kv.partition("=")
                try:
                    v = json.loads(v)
                except Exception:
                    pass
                ov[k.strip()] = v
            if not a:
                raise SystemExit("usage: run.py speak <script.txt | episode folder> [--name N] [--model M] [--redo 3,7]")
            speak.main(" ".join(a).strip('"'), name=name, model=model, redo=redo, style=style, pace=pace, s3gen=s3g,
                       flow=(None if flow is None else str(flow).lower() not in ("0", "off", "false", "no")),
                       overrides=ov)
        else:
            print(__doc__)
    except SystemExit as e:
        if str(e) not in ("", "0", "None"):
            print(f"\n  !! {e}")
        sys.exit(1)


if __name__ == "__main__":
    main()
